SOFTWARE_ENGINEERING_CHAPTER_7_QUIZ = [
{"q":"What is a Software Requirement?","o":["A service, function, or constraint that the system must provide or satisfy","A finished source-code file","A project marketing slogan","A server backup only"],"a":"A service, function, or constraint that the system must provide or satisfy"},
{"q":"What is Requirements Engineering?","o":["The systematic process of discovering, analyzing, documenting, validating, and managing requirements","Only writing a user interface","Only testing after deployment","Only negotiating a project budget"],"a":"The systematic process of discovering, analyzing, documenting, validating, and managing requirements"},
{"q":"Why are good requirements important?","o":["They provide a foundation for design, implementation, testing, planning, and stakeholder satisfaction","They guarantee that no maintenance will ever be needed","They replace all software testing","They prevent every requirement from changing"],"a":"They provide a foundation for design, implementation, testing, planning, and stakeholder satisfaction"},
{"q":"What is a Feasibility Study?","o":["An investigation of whether a proposed project is technically, economically, organizationally, and schedulably realistic","A final acceptance test","A database design document","A user-interface prototype only"],"a":"An investigation of whether a proposed project is technically, economically, organizationally, and schedulably realistic"},
{"q":"Who is a Stakeholder?","o":["A person or organization that affects, is affected by, or has an interest in the system","Only the lead developer","Only the person who pays for a server","Only an external auditor"],"a":"A person or organization that affects, is affected by, or has an interest in the system"},
{"q":"What is Requirements Elicitation?","o":["Discovering and collecting requirements from stakeholders and other relevant sources","Writing production code","Deleting conflicting requirements without discussion","Deploying the application"],"a":"Discovering and collecting requirements from stakeholders and other relevant sources"},
{"q":"Which technique is useful for collecting information from many users?","o":["Questionnaires","Only pair programming","Only source-code review","Only server monitoring"],"a":"Questionnaires"},
{"q":"What is Observation used for?","o":["Watching users perform real work to discover steps, exceptions, and practices they may not describe completely","Replacing every stakeholder interview with a database query","Testing network bandwidth only","Writing an SRS without users"],"a":"Watching users perform real work to discover steps, exceptions, and practices they may not describe completely"},
{"q":"What is a Requirements Workshop?","o":["A facilitated meeting where stakeholders and analysts discuss needs, conflicts, priorities, and agreements","A deployment script","A private coding session","A performance benchmark"],"a":"A facilitated meeting where stakeholders and analysts discuss needs, conflicts, priorities, and agreements"},
{"q":"What is a User Story?","o":["A requirement expressed from a user's perspective, often using As a user, I want a feature, so that a benefit","A complete technical architecture","A database normalization rule","A legal regulation"],"a":"A requirement expressed from a user's perspective, often using As a user, I want a feature, so that a benefit"},
{"q":"What is a Functional Requirement?","o":["A function or service that the system must provide","A response-time target only","A privacy law only","A design color"],"a":"A function or service that the system must provide"},
{"q":"What is a Non-functional Requirement?","o":["A quality attribute or constraint such as performance, security, reliability, availability, or usability","A login feature only","A list of stakeholders","A programming variable"],"a":"A quality attribute or constraint such as performance, security, reliability, availability, or usability"},
{"q":"What is the difference between User Requirements and System Requirements?","o":["User Requirements are high-level and user-oriented; System Requirements are more detailed and guide developers, designers, and testers","User Requirements are always code while System Requirements are marketing text","They are always exactly identical","System Requirements are never testable"],"a":"User Requirements are high-level and user-oriented; System Requirements are more detailed and guide developers, designers, and testers"},
{"q":"What is an SRS?","o":["A Software Requirements Specification document that organizes functional, non-functional, interface, constraint, assumption, and other requirements","A source-code repository","A test server","A project invoice"],"a":"A Software Requirements Specification document that organizes functional, non-functional, interface, constraint, assumption, and other requirements"},
{"q":"Which is a characteristic of a good requirement?","o":["It is correct, complete, consistent, unambiguous, verifiable, feasible, and traceable","It is vague and open to many interpretations","It cannot be tested","It contradicts another requirement"],"a":"It is correct, complete, consistent, unambiguous, verifiable, feasible, and traceable"},
{"q":"Why is ‘The system should respond quickly’ a weak requirement?","o":["‘Quickly’ is ambiguous and does not define a measurable response target","It is too precise","It is a complete security requirement","It contains a test case"],"a":"‘Quickly’ is ambiguous and does not define a measurable response target"},
{"q":"What is Requirements Validation?","o":["Checking that requirements are correct, complete, clear, consistent, feasible, and testable","Implementing every requirement immediately","Changing requirements without approval","Deploying a prototype to production"],"a":"Checking that requirements are correct, complete, clear, consistent, feasible, and testable"},
{"q":"What is Requirements Management?","o":["Controlling requirements and their changes throughout the project lifecycle, including analysis, approval, updating, and implementation","Deleting the SRS after the first release","Only collecting requirements once","Replacing stakeholder communication"],"a":"Controlling requirements and their changes throughout the project lifecycle, including analysis, approval, updating, and implementation"},
{"q":"What is Requirements Traceability?","o":["Linking a requirement to its source, design, implementation, and test so its progress and coverage can be followed","Tracking only the number of developers","Measuring server temperature","Copying requirements into an email"],"a":"Linking a requirement to its source, design, implementation, and test so its progress and coverage can be followed"},
{"q":"Why is Requirements Prioritization necessary?","o":["Time, budget, team capacity, and value are limited, so important requirements should be addressed first","Every feature has exactly the same value","Prioritization prevents all requirements from changing","It replaces feasibility analysis"],"a":"Time, budget, team capacity, and value are limited, so important requirements should be addressed first"},
]
