        dfa1.node('q1', 'Odd (q1)', shape='circle')
        dfa1.edge('S', 'q0')
        dfa1.edge('q0', 'q1', label='0')
        dfa1.edge('q1', 'q0', label='0')
        dfa1.edge('q0', 'q0', label='1')
        dfa1.edge('q1', 'q1', label='1')
