 if mode=='Prim MST':
  start=st.selectbox('Starting vertex',['A','B','C','D'],key='algorithm_design_ch15_prim_start');st.write(f'Prim starts at {start} and grows one connected tree.');st.dataframe([{'Step':1,'Chosen':'A-B','Weight':2},{'Step':2,'Chosen':'B-D','Weight':3},{'Step':3,'Chosen':'D-C','Weight':1}],use_container_width=True);st.success('MST edges: A-B, B-D, D-C; total weight = 6')
 elif mode=='Kruskal MST':
  st.write('Edges sorted by weight: C-D=1, A-B=2, B-D=3, A-C=4');st.dataframe([{'Step':1,'Edge':'C-D = 1','Action':'Add'},{'Step':2,'Edge':'A-B = 2','Action':'Add'},{'Step':3,'Edge':'B-D = 3','Action':'Add'},{'Step':4,'Edge':'A-C = 4','Action':'Reject — cycle'}],use_container_width=True);st.success('MST total weight = 6')
 else:
  source=st.selectbox('Source vertex',['A','B','C','D'],key='algorithm_design_ch15_dijkstra_source');st.write(f'Dijkstra source: {source}');st.dataframe([{'Vertex':'A','Distance':0,'Previous':'—'},{'Vertex':'B','Distance':2,'Previous':'A'},{'Vertex':'C','Distance':5,'Previous':'A'},{'Vertex':'D','Distance':5,'Previous':'B'}],use_container_width=True);st.success('Shortest path to D: A → B → D; distance = 5')
