 show_algorithm_ch6_diagram('06_knapsack_reconstruction.png','Knapsack Solution Reconstruction')
 show_algorithm_ch6_diagram('07_lcs_table.png','LCS Dynamic Programming Table')
 show_algorithm_ch6_diagram('08_lcs_backtrack.png','LCS Backtracking Path')
 show_algorithm_ch6_diagram('09_matrix_chain_comparison.png','Matrix Chain Multiplication Comparison')
 show_algorithm_ch6_diagram('10_matrix_chain_table.png','Matrix Chain DP Table')
 show_algorithm_ch6_diagram('11_generic_dp_table.png','Generic Dynamic Programming Table')
